import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',stage='recognized',**kw):A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage=stage,issuer_treatment=s,**kw)]))
add(196,'Exercice 2025 : segment Data Centers correspondant à Helios, actifs 1,863911 Md$ et passifs 1,098739 Md$. Revenus 8,433 M$ d’intérêts, perte nette segment 1,098 M$, sans loyer HPC reconnu. Charges d’intérêt des notes corporate allouées au Treasury, donc rentabilité segment ne couvre pas tout financement du groupe ; comparatifs segments 2023–2024 recast présentés non audités.','Our Data Centers segment develops, and will in the future operate, HPC infrastructure','data_center_segment_pre_operating_scope',measurement_basis='FY2025_DataCenters_interest_only;corporate_note_interest_Treasury;segment_assets_not_cash')
add(197,'Fin 2025 : prêts crypto nets 1,078929 Md$, emprunts crypto 2,417268 Md$ dont 2,361161 Md$ courants. Collatéral reçu 1,333059 Md$ entraîne restitution ; collatéral posté 185,78 M$ plus actifs conservés en DeFi, pas une réserve libre. Aucun impayé déclaré ne prouve une absence de risque futur. Activité de trading et lending non attribuée à l’IA.','Collateral payable associated with digital asset loans receivable','crypto_collateral_restitution_and_borrowing_scope',c='context',counterparty_evidence='anonymous')
add(198,'En 2025, levée de juin : 477,8 M$ net reçus par Galaxy, ventes secondaires sans produit pour la société. Placement stratégique d’octobre 460 M$ inclut actions de dirigeants ; seul produit primaire à compter comme financement issuer. Reclassification de passifs de rémunération 8 M$ et 9,3 M$ en equity sans encaissement. Parts LP/B échangées 1:1 ne constituent pas une nouvelle levée cash.','The Company did not receive any proceeds from the sale of Class A common stock by the selling stockholders.','primary_equity_proceeds_exclude_secondary_sales',stage='drawn_or_paid',measurement_basis='June2025_primary_net477_8m;October460m_mixed_primary_secondary')
add(199,'T1 2026 : gains réalisés 26,1 M$ et pertes non réalisées 238,6 M$ sur investissements. Valeur alternative 145,994 M$, dépréciations et revalorisations distinctes des flux cash. Variation trimestrielle d’actif ou perte non réalisée ne peut pas être attribuée à Helios sans preuve.','Net unrealized gains / (losses) related to investments were $(238.6) million','investment_unrealized_loss_not_project_cashflow',c='context')
add(200,'Mars 2026 : VIE non consolidées, exposition maximale 408,861 M$ composée de juste valeur 360,039 M$ et 48,822 M$ d’apports non financés. Sans garanties de performance autres que capitaux propres engagés ; la variation depuis décembre est un stock, pas un remboursement cash démontré. Aucune attribution de l’ensemble aux datacenters.','other than its own capital commitments.','unconsolidated_vie_max_exposure_scope',c='context',counterparty_evidence='anonymous',measurement_basis='March2026_408_861m_max_exposure;not_plus_Dec_stock')
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
 t=json.loads(Path(M[a['index']]['path']).read_text())['text']
 for r in a['rows']:assert r['quote'] in t,(a['index'],r['quote'])
